  return new Observable<T>((subscriber) => {
    let iterator: AsyncIterator<T> | undefined;
    let nextPending = false;
    let completedNaturally = false;
    let iteratorReturned = false;

    const returnIterator = () => {
      if (!iteratorReturned && iterator) {
        iteratorReturned = true;
        const returnMethod = iterator.return;
        if (returnMethod) {
          try {
            Promise.resolve(returnMethod.call(iterator)).catch(() => undefined);
          } catch {
            // Ignore errors from iterator.return during unsubscribe.
          }
        }
      }
    };

    subscriber.add(() => {
      if (!completedNaturally) {
        returnIterator();
      }
    });

    const scheduleNext = () => {
      if (subscriber.closed || nextPending) {
        return;
      }

      nextPending = true;
      executeSchedule(subscriber, scheduler, () => {
        if (subscriber.closed) {
          nextPending = false;
          return;
        }

        let nextResult: PromiseLike<IteratorResult<T>>;
        try {
          nextResult = iterator!.next();
        } catch (err) {
          nextPending = false;
          subscriber.error(err);
          return;
        }

        Promise.resolve(nextResult).then(
          (result) => {
            nextPending = false;
            if (subscriber.closed) {
              return;
            }
            if (result.done) {
              completedNaturally = true;
              subscriber.complete();
            } else {
              subscriber.next(result.value);
              if (!subscriber.closed) {
                scheduleNext();
              }
            }
          },
          (err) => {
            nextPending = false;
            if (!subscriber.closed) {
              subscriber.error(err);
            }
          }
        );
      });
    };

    executeSchedule(subscriber, scheduler, () => {
      if (!subscriber.closed) {
        iterator = input[Symbol.asyncIterator]();
        scheduleNext();
      }
    });
