{
  if (!input) {
    throw new Error('Iterable cannot be null');
  }
  return new Observable<T>((subscriber) => {
    let iterator: AsyncIterator<T> | undefined;
    let done = false;
    let nextPending = false;
    let returnCalled = false;

    const returnIterator = () => {
      if (!iterator || done || returnCalled) {
        return;
      }
      returnCalled = true;
      const returnMethod = iterator.return;
      if (returnMethod) {
        try {
          Promise.resolve(returnMethod.call(iterator)).catch(() => {});
        } catch {
          // Ignore errors from returning an iterator after the subscriber has closed.
        }
      }
    };

    subscriber.add(() => returnIterator());

    const scheduleNext = () => {
      if (subscriber.closed || done || nextPending || !iterator) {
        return;
      }

      executeSchedule(subscriber, scheduler, () => {
        if (subscriber.closed || done || nextPending) {
          return;
        }

        nextPending = true;
        let nextResult: PromiseLike<IteratorResult<T>>;
        try {
          nextResult = iterator!.next();
        } catch (err) {
          nextPending = false;
          subscriber.error(err);
          return;
        }

        Promise.resolve(nextResult).then(
          (result) => {
            nextPending = false;
            if (subscriber.closed) {
              return;
            }
            if (result.done) {
              done = true;
              subscriber.complete();
            } else {
              subscriber.next(result.value);
              scheduleNext();
            }
          },
          (err) => {
            nextPending = false;
            if (!subscriber.closed) {
              subscriber.error(err);
            }
          }
        );
      });
    };

    // Schedule the initial creation of the iterator from the iterable. This is so the code in the iterable is
    // not called until the scheduled job fires.
    executeSchedule(subscriber, scheduler, () => {
      if (subscriber.closed) {
        return;
      }
      iterator = input[Symbol.asyncIterator]();
      scheduleNext();
    });
  });
}

interface ReadableStreamDefaultReaderLike<T> {
  // HACK: As of TS 4.2.2, The provided types for the iterator results of a `ReadableStreamDefaultReader`
  // are significantly different enough from `IteratorResult` as to cause compilation errors.
  // The type at the time is `ReadableStreamDefaultReadResult`.
  read(): PromiseLike<
    | {
        done: false;
        value: T;
      }
    | { done: true; value?: undefined }
  >;
  cancel?(): PromiseLike<void>;
  releaseLock(): void;
}

