{
  if (!input) {
    throw new Error('Iterable cannot be null');
  }
  return new Observable<T>((subscriber) => {
    let iterator: AsyncIterator<T> | undefined;
    let completed = false;
    let returned = false;

    const scheduleNext = () => {
      executeSchedule(subscriber, scheduler, () => {
        if (subscriber.closed) {
          return;
        }

        let next: PromiseLike<IteratorResult<T>>;
        try {
          next = iterator!.next();
        } catch (err) {
          subscriber.error(err);
          return;
        }

        Promise.resolve(next)
          .then(
            (result) => {
              if (subscriber.closed) {
                return;
              }
              if (result.done) {
                completed = true;
                subscriber.complete();
              } else {
                subscriber.next(result.value);
                if (!subscriber.closed) {
                  scheduleNext();
                }
              }
            },
            (err) => {
              if (!subscriber.closed) {
                subscriber.error(err);
              }
            }
          )
          .catch(() => undefined);
      });
    };

    executeSchedule(subscriber, scheduler, () => {
      if (!subscriber.closed) {
        try {
          iterator = input[Symbol.asyncIterator]();
          scheduleNext();
        } catch (err) {
          subscriber.error(err);
        }
      }
    });

    return () => {
      if (!completed && !returned) {
        returned = true;
        const currentIterator = iterator;
        const returnMethod = currentIterator?.return;
        if (isFunction(returnMethod)) {
          try {
            Promise.resolve(returnMethod.call(currentIterator)).catch(() => undefined);
          } catch {
            // Ignore synchronous errors from iterator cleanup.
          }
        }
      }
    };
  });
}

